// Synthetic replica of expo-sqlite@15 sources (TS, no JSX). The published
// package ships the precompiled build/ output; this src mirrors it. The native
// ExpoSQLite module is only present on a device.
import { requireNativeModule } from "expo-modules-core";

const ExpoSQLiteNativeModule = requireNativeModule("ExpoSQLite");

export const EXPO_SQLITE_OK = "EXPO_SQLITE_OK";

export interface SQLiteDatabase {
  execAsync(sql: string): Promise<void>;
  closeAsync(): Promise<void>;
}

export function openDatabaseSync(databaseName: string): SQLiteDatabase {
  if (!ExpoSQLiteNativeModule) {
    throw new Error(`The ExpoSQLite native module is unavailable for "${databaseName}".`);
  }
  return ExpoSQLiteNativeModule.openDatabaseSync(databaseName) as SQLiteDatabase;
}

export async function openDatabaseAsync(databaseName: string): Promise<SQLiteDatabase> {
  return openDatabaseSync(databaseName);
}

export function deleteDatabaseSync(databaseName: string): void {
  ExpoSQLiteNativeModule?.deleteDatabaseSync?.(databaseName);
}
